import{_ as e,a as r,c as a,ac as d}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"云原生服务网格Istio","description":"按2019年版24章整理 Istio 的原理、实践、历史架构与源码导读。","frontmatter":{"title":"云原生服务网格Istio","description":"按2019年版24章整理 Istio 的原理、实践、历史架构与源码导读。","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"书籍导读","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"书单 · 计算机与软件工程 · 架构、运维与云原生","summary":"按2019年版24章整理 Istio 的原理、实践、历史架构与源码导读。","status":"active","related":[{"title":"Kubernetes权威指南（第4版）","link":"/life/personal/books/computing/kubernetes-guide","kind":"书籍导读","scope":"general","audience":"general"}],"prev":false,"next":{"text":"Kubernetes权威指南（第4版）","link":"/life/personal/books/computing/kubernetes-guide"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"Kubernetes权威指南（第4版）","link":"/life/personal/books/computing/kubernetes-guide"}},"headers":[],"relativePath":"life/personal/books/computing/istio.md","filePath":"life/personal/books/computing/istio.md"}'),o={name:"life/personal/books/computing/istio.md"};function i(l,t,n,s,h,p){return r(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="云原生服务网格istio" tabindex="-1">云原生服务网格Istio <a class="header-anchor" href="#云原生服务网格istio" aria-label="Permalink to &quot;云原生服务网格Istio&quot;">​</a></h1><p><a href="./../overview">返回分类书单</a></p><p><strong>分类：计算机与软件工程 / 架构、运维与云原生</strong></p><h2 id="书籍简介" tabindex="-1">书籍简介 <a class="header-anchor" href="#书籍简介" aria-label="Permalink to &quot;书籍简介&quot;">​</a></h2><p>这本书的阅读方向是服务网格如何管理服务之间的通信。它适合已经理解容器、Kubernetes 和基本微服务通信，希望继续学习流量治理、服务身份与观测能力的读者。</p><p>阅读时需要区分业务代码、代理和控制平面的职责。网格可以统一处理部分通信策略，但业务幂等、数据一致性和业务语义仍然需要应用自身明确设计。</p><h2 id="版本说明" tabindex="-1">版本说明 <a class="header-anchor" href="#版本说明" aria-label="Permalink to &quot;版本说明&quot;">​</a></h2><p>本页对应张超盟、章鑫、徐中虎、徐飞著，电子工业出版社 <strong>2019 年版</strong>《云原生服务网格Istio：原理、实践、架构与源码解析》，ISBN <strong>9787121366536</strong>。根据该版公开书目与随书代码仓库整理 24 章。书单省略了副标题，实际藏书可据 ISBN 再确认；书中 Pilot、Mixer、Citadel、Galley 等架构属于当时版本，不能当作当前 Istio 的组件清单。</p><h2 id="作者与背景" tabindex="-1">作者与背景 <a class="header-anchor" href="#作者与背景" aria-label="Permalink to &quot;作者与背景&quot;">​</a></h2><p>作者为张超盟、章鑫、徐中虎、徐飞。随书仓库属于华为云原生丛书并提供作者入口、环境配置与章节代码；华为云官方活动页也列出张超盟与本书的关联。其专业性可从服务网格工程实践和可核对代码理解，本页不把成书时或活动时的职务当作当前职务，也不将四人的履历一概而论。</p><h2 id="目标读者" tabindex="-1">目标读者 <a class="header-anchor" href="#目标读者" aria-label="Permalink to &quot;目标读者&quot;">​</a></h2><p>适合熟悉容器、Kubernetes Service 和 HTTP 调用，希望研究流量治理或服务网格历史架构的开发、平台工程人员。刚接触容器的人应先补工作负载与服务发现，再学习代理和控制平面。</p><h2 id="章节介绍" tabindex="-1">章节介绍 <a class="header-anchor" href="#章节介绍" aria-label="Permalink to &quot;章节介绍&quot;">​</a></h2><table tabindex="0"><thead><tr><th>章节</th><th>阅读关注点</th></tr></thead><tbody><tr><td>第1章 你好，Istio</td><td>介绍服务网格的背景与问题，认识 Istio 在服务通信中的位置。</td></tr><tr><td>第2章 Istio 架构概述</td><td>建立当时控制平面与数据平面的组件关系。</td></tr><tr><td>第3章 非侵入的流量治理</td><td>解释代理如何参与路由、负载均衡和通信策略。</td></tr><tr><td>第4章 可扩展的策略和遥测</td><td>理解策略与观测能力的扩展方式，明确采集信息的范围。</td></tr><tr><td>第5章 可插拔的服务安全</td><td>将服务身份、加密和访问策略连接起来。</td></tr><tr><td>第6章 透明的 Sidecar 机制</td><td>分析应用流量怎样经过代理，以及透明接入的前提。</td></tr><tr><td>第7章 多集群服务治理</td><td>讨论服务跨集群分布后的发现、连接和管理问题。</td></tr><tr><td>第8章 环境准备</td><td>按书中版本搭建实践环境，为后续应用实验建立基础。</td></tr><tr><td>第9章 流量监控</td><td>观察请求指标和调用信息，关联应用行为与网格观测。</td></tr><tr><td>第10章 灰度发布</td><td>使用流量分配逐步引入新版本，并检查路由是否按预期生效。</td></tr><tr><td>第11章 流量治理</td><td>将通信规则应用于示例，分析正常与异常请求的行为。</td></tr><tr><td>第12章 服务保护</td><td>讨论服务遭遇压力或依赖故障时的保护策略。</td></tr><tr><td>第13章 多集群管理</td><td>把跨集群概念落实到运行配置与验证。</td></tr><tr><td>第14章 司令官 Pilot</td><td>研究服务发现、配置与代理控制的历史架构。</td></tr><tr><td>第15章 守护神 Mixer</td><td>理解当时策略检查和遥测处理的组件设计。</td></tr><tr><td>第16章 安全碉堡 Citadel</td><td>分析服务身份与证书相关机制在旧架构中的组织。</td></tr><tr><td>第17章 高性能代理 Envoy</td><td>认识数据平面代理的能力及其与控制平面的联系。</td></tr><tr><td>第18章 代理守护进程 Pilot-agent</td><td>观察代理进程的启动与管理职责。</td></tr><tr><td>第19章 配置中心 Galley</td><td>研究当时配置处理与分发相关组件的设计。</td></tr><tr><td>第20章 Pilot 源码解析</td><td>从关键流程和数据结构追踪代理配置的生成与交互。</td></tr><tr><td>第21章 Mixer 源码解析</td><td>进入历史版本的策略、适配与遥测处理实现。</td></tr><tr><td>第22章 Citadel 源码解析</td><td>追踪身份和证书处理的核心实现路径。</td></tr><tr><td>第23章 Envoy 源码解析</td><td>从代理关键代码理解请求处理与扩展机制。</td></tr><tr><td>第24章 Galley 源码解析</td><td>通过实现认识配置处理流程及组件之间的连接。</td></tr><tr><td>附录 A、B</td><td>分别介绍源码仓库，以及实践经验和总结。</td></tr></tbody></table><h2 id="读后感" tabindex="-1">读后感 <a class="header-anchor" href="#读后感" aria-label="Permalink to &quot;读后感&quot;">​</a></h2><p>以下为本站阅读评析，用可实践的阅读目标表达收获，不代表书单提供者已经读完、任职或完成相应项目。版本未明时，评析只针对本页明确标注的主题或参考版本。</p><h3 id="金句摘抄或阅读提炼" tabindex="-1">金句摘抄或阅读提炼 <a class="header-anchor" href="#金句摘抄或阅读提炼" aria-label="Permalink to &quot;金句摘抄或阅读提炼&quot;">​</a></h3><blockquote><p>透明代理隐藏了接入动作，却没有消除排障责任。</p></blockquote><p>这是本站原创阅读提炼，不是原书引文；没有可核对页码的原文不作逐字摘抄。</p><h3 id="个人收获" tabindex="-1">个人收获 <a class="header-anchor" href="#个人收获" aria-label="Permalink to &quot;个人收获&quot;">​</a></h3><p>沿一条请求画出应用、Sidecar、目标服务和控制配置的关系，标明超时、重试与观测分别发生在哪里。进一步比较没有网格时的应用行为，可以帮助判断治理能力解决了什么、引入了哪些额外故障点。</p><h3 id="客观评价与阅读建议" tabindex="-1">客观评价与阅读建议 <a class="header-anchor" href="#客观评价与阅读建议" aria-label="Permalink to &quot;客观评价与阅读建议&quot;">​</a></h3><p>这版把实践与历史源码连接起来，适合研究设计演变；Mixer、Galley 等旧组件的章节不宜当作当前部署手册。先固定书中版本复现一项流量实验，再利用历史与当前官方文档比较变化，避免边升级边猜含义。</p><p><strong>推荐语（本站原创，非原书引用）：</strong> 推荐给已有 Kubernetes 基础、想理解通信治理代价的人；读清一条请求，比先装齐所有组件更有价值。</p><h2 id="来源与核对入口" tabindex="-1">来源与核对入口 <a class="header-anchor" href="#来源与核对入口" aria-label="Permalink to &quot;来源与核对入口&quot;">​</a></h2><ul><li><a href="https://book.douban.com/subject/34438220/" target="_blank" rel="noopener noreferrer">2019 年版书目与完整目录</a>：ISBN、24 章与附录结构的核对来源。</li><li><a href="https://github.com/cloudnativebooks/cloud-native-istio" target="_blank" rel="noopener noreferrer">本书随书代码仓库</a>：核对完整书名、示例应用与各章代码入口。</li><li><a href="https://istio.io/latest/docs/" target="_blank" rel="noopener noreferrer">Istio 官方文档</a>：当前概念与操作参考，不作为原书目录证据。</li><li><a href="https://istio.io/archive/" target="_blank" rel="noopener noreferrer">Istio 历史版本文档</a>：确认书中版本后，选择相应文档进行比对。</li><li><a href="https://bbs.huaweicloud.com/live/edu_live/202107231900.html" target="_blank" rel="noopener noreferrer">华为云官方活动页：作者与著作信息</a>：作者背景的历史核对入口。</li></ul>',26)])])}const b=e(o,[["render",i]]);export{u as __pageData,b as default};
